set-variable.value:
@{
      try {
        var raw = context.Request.Body.As<string>(preserveContent: true);
        if (System.Text.Encoding.UTF8.GetByteCount(raw) > 65536) { return "Request exceeds 64 KiB"; }
        var body = Newtonsoft.Json.Linq.JObject.Parse(raw);
        if (body["input"] == null || (body["input"].Type != Newtonsoft.Json.Linq.JTokenType.String && body["input"].Type != Newtonsoft.Json.Linq.JTokenType.Array)) { return "input must be text or a Responses input list"; }
        if (body["stream"] != null && body["stream"].Type != Newtonsoft.Json.Linq.JTokenType.Boolean) { return "stream must be boolean"; }
        if (body["background"] != null && (body["background"].Type != Newtonsoft.Json.Linq.JTokenType.Boolean || (bool)body["background"])) { return "background requests are not supported"; }
        if (body["previous_response_id"] != null || body["conversation"] != null) { return "Use stateless input; conversation and previous_response_id are not supported"; }
        if (body["tools"] != null) {
          var tools = body["tools"] as Newtonsoft.Json.Linq.JArray;
          if (tools == null) { return "tools must be an array"; }
          foreach (var tool in tools) {
            if (!(tool is Newtonsoft.Json.Linq.JObject) || (string)tool["type"] != "web_search") { return "This lab supports only the hosted web_search tool"; }
          }
          if (tools.Count > 0 && (body["urls_csv"] == null || body["urls_csv"].Type != Newtonsoft.Json.Linq.JTokenType.String || string.IsNullOrWhiteSpace((string)body["urls_csv"]))) { return "urls_csv is required when web_search is offered"; }
          if (tools.Count > 0 && System.Text.Encoding.UTF8.GetByteCount((string)body["urls_csv"]) > 16000) { return "urls_csv exceeds 16000 bytes"; }
        }
        if (body["max_output_tokens"] != null && (body["max_output_tokens"].Type != Newtonsoft.Json.Linq.JTokenType.Integer || (int)body["max_output_tokens"] < 16 || (int)body["max_output_tokens"] > 4096)) { return "max_output_tokens must be between 16 and 4096"; }
        return "";
      } catch { return "Invalid JSON request"; }
    }

@{
      var body = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["originalRequest"]);
      var tools = body["tools"] as Newtonsoft.Json.Linq.JArray;
      return tools != null && tools.Count > 0;
    }

@{
      var body = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["originalRequest"]);
      body.Remove("urls_csv");
      body["model"] = "{deployment}";
      body["store"] = false;
      if (body["max_output_tokens"] == null) { body["max_output_tokens"] = 4096; }
      return body.ToString(Newtonsoft.Json.Formatting.None);
    }

@{
          try {
            var raw = (string)context.Variables["initialBody"];
            var contentType = ((IResponse)context.Variables["initial"]).Headers.GetValueOrDefault("Content-Type", "");
            if (!contentType.StartsWith("text/event-stream", StringComparison.OrdinalIgnoreCase)) { return Newtonsoft.Json.Linq.JObject.Parse(raw).ToString(Newtonsoft.Json.Formatting.None); }
            string terminal = "";
            foreach (var frame in raw.Replace("\r\n", "\n").Split(new string[] { "\n\n" }, StringSplitOptions.RemoveEmptyEntries)) {
              string data = "";
              foreach (var line in frame.Split(new string[] { "\n" }, StringSplitOptions.None)) {
                if (line.StartsWith("data:")) { data += line.Substring(5).TrimStart() + "\n"; }
              }
              if (string.IsNullOrWhiteSpace(data) || data.Trim() == "[DONE]") { continue; }
              var evt = Newtonsoft.Json.Linq.JObject.Parse(data);
              var type = (string)evt["type"];
              if (type == "response.completed" || type == "response.failed" || type == "response.incomplete") {
                terminal = evt["response"].ToString(Newtonsoft.Json.Formatting.None);
              }
              if (type == "error") { return ""; }
            }
            return terminal;
          } catch { return ""; }
        }

@{
          var response = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["initialResponse"]);
          if ((string)response["status"] != "completed") { return false; }
          var output = response["output"] as Newtonsoft.Json.Linq.JArray;
          if (output == null) { return false; }
          foreach (var item in output) {
            if ((string)item["type"] == "web_search_call" && (string)item["status"] == "completed") { return true; }
          }
          return false;
        }

when.set-body:
@{
          var original = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["originalRequest"]);
          var csv = (string)original["urls_csv"];
          original.Remove("urls_csv");
          return new Newtonsoft.Json.Linq.JObject(
            new Newtonsoft.Json.Linq.JProperty("original_request", original),
            new Newtonsoft.Json.Linq.JProperty("initial_response", Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["initialResponse"])),
            new Newtonsoft.Json.Linq.JProperty("urls_csv", csv),
            new Newtonsoft.Json.Linq.JProperty("stream", (bool?)original["stream"] ?? false)
          ).ToString(Newtonsoft.Json.Formatting.None);
        }
